#include <sys/types.h>

#include <errno.h>
#include <stdlib.h>
#include <string.h>

#include "tmux.h"

/* Create a buffer. */
struct buffer *
buffer_create(size_t size)
{
	struct buffer	*b;

	if (size == 0)
		fatalx("zero size");

	b = xcalloc(1, sizeof *b);

	b->base = xmalloc(size);
	b->space = size;

	return (b);
}

/* Destroy a buffer. */
void
buffer_destroy(struct buffer *b)
{
	xfree(b->base);
	xfree(b);
}

/* Ensure free space for size in buffer. */
void
buffer_ensure(struct buffer *b, size_t size)
{
#ifdef TMUX_SMALL_MEMORY
	size_t	needed, newspace, remainder;
#endif

	if (size == 0)
		fatalx("zero size");

	if (BUFFER_FREE(b) >= size)
		return;

	if (b->off > 0) {
		if (b->size > 0)
			memmove(b->base, b->base + b->off, b->size);
		b->off = 0;
	}

	if (SIZE_MAX - b->size < size)
		fatalx("size too big");
#ifdef TMUX_SMALL_MEMORY
	needed = b->size + size;
	if (b->space >= needed)
		return;
	/* Bound unused capacity without overflowing the 16-bit size_t. */
	newspace = needed;
	remainder = needed % TMUX_IO_SIZE;
	if (remainder != 0 && SIZE_MAX - needed >= TMUX_IO_SIZE - remainder)
		newspace += TMUX_IO_SIZE - remainder;
	b->base = xrealloc(b->base, 1, newspace);
	b->space = newspace;
#else
	while (b->space < b->size + size) {
		b->base = xrealloc(b->base, 2, b->space);
		b->space *= 2;
	}
#endif
}

/* Adjust buffer after data appended. */
void
buffer_add(struct buffer *b, size_t size)
{
	if (size == 0)
		fatalx("zero size");
	if (size > b->space - b->size)
		fatalx("overflow");

	b->size += size;
}

/* Adjust buffer after data removed. */
void
buffer_remove(struct buffer *b, size_t size)
{
#ifdef TMUX_SMALL_MEMORY
	u_char	*base;
	int	 saved_errno;
#endif

	if (size == 0)
		fatalx("zero size");
	if (size > b->size)
		fatalx("underflow");

	b->size -= size;
	b->off += size;
#ifdef TMUX_SMALL_MEMORY
	if (b->size == 0) {
		b->off = 0;
		if (b->space > TMUX_IO_SIZE) {
			/* Shrinking is optional; failure must retain a usable buffer. */
			saved_errno = errno;
#ifdef TMUX_NATIVE_211BSD
			/* Native realloc frees its input even when allocation fails. */
			base = malloc(TMUX_IO_SIZE);
			if (base != NULL)
				free(b->base);
#else
			base = realloc(b->base, TMUX_IO_SIZE);
#endif
			errno = saved_errno;
			if (base != NULL) {
				b->base = base;
				b->space = TMUX_IO_SIZE;
			}
		}
	}
#endif
}

/* Copy data into a buffer. */
void
buffer_write(struct buffer *b, const void *data, size_t size)
{
	buffer_ensure(b, size);
	memcpy(BUFFER_IN(b), data, size);
	buffer_add(b, size);
}

/* Copy data out of a buffer. */
void
buffer_read(struct buffer *b, void *data, size_t size)
{
	if (size == 0)
		fatalx("zero size");
	if (size > b->size)
		fatalx("underflow");

	memcpy(data, BUFFER_OUT(b), size);
	buffer_remove(b, size);
}

/* Store an 8-bit value. */
void
buffer_write8(struct buffer *b, uint8_t n)
{
	buffer_ensure(b, 1);
	BUFFER_IN(b)[0] = n;
	b->size++;
}

/* Extract an 8-bit value. */
uint8_t
buffer_read8(struct buffer *b)
{
	uint8_t	n;

	n = BUFFER_OUT(b)[0];
	buffer_remove(b, 1);
	return (n);
}
